import{_ as a,o as l,c as r,ag as o}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),t={name:"changelog.md"};function i(n,e,s,d,c,g){return l(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to Claude Deck are documented here. The format follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>.</p><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>CC Bridge</strong> — live terminal bridge to Claude Code sessions in tmux <ul><li>Multi-terminal grid (up to 4 panes in auto-layout)</li><li>Per-pane read-only/interactive mode, fullscreen, attach/detach</li><li>Session discovery via <code>tmux list-panes</code> with auto-refresh</li><li>Spawn new sessions (plain, worktree, or resume mode)</li><li>Kill sessions with optional worktree cleanup</li><li>WebSocket PTY relay with xterm.js (WebGL rendering)</li></ul></li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>CC Bridge</strong> — prevent orphaned <code>tmux attach-session</code> processes on server reload</li><li><strong>CC Bridge</strong> — fix terminal rendering in React StrictMode</li></ul><h2 id="_1-0-0-—-2026-01-22" tabindex="-1">1.0.0 — 2026-01-22 <a class="header-anchor" href="#_1-0-0-—-2026-01-22" aria-label="Permalink to &quot;1.0.0 — 2026-01-22&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Initial release of Claude Deck</li><li><strong>Dashboard</strong> — configuration status and usage overview</li><li><strong>MCP Server Management</strong> — add, edit, test, configure servers (global + project)</li><li><strong>Commands</strong> — create and manage slash commands</li><li><strong>Plugins</strong> — install, configure, and manage plugins</li><li><strong>Hooks</strong> — configure event hooks for Claude Code lifecycle</li><li><strong>Permissions</strong> — manage allow/deny rules for tools</li><li><strong>Backup &amp; Restore</strong> — full configuration backup and restore</li><li><strong>Project Management</strong> — project-specific configurations</li><li><strong>Usage Tracking</strong> — token usage and cost visualization</li></ul><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><ul><li>FastAPI backend with async SQLAlchemy + SQLite</li><li>React frontend with TypeScript, Vite, and shadcn/ui</li><li>RESTful API at <code>/api/v1/</code></li></ul><hr><p>See the full changelog on <a href="https://github.com/adrirubio/claude-deck/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">GitHub</a>.</p>',14)])])}const m=a(t,[["render",i]]);export{u as __pageData,m as default};
